class Solution { public: int minOperations(vector<int>& nums,int x){int target=accumulate(nums.begin(),nums.end(),0)-x;if(target<0)return -1;if(!target)return nums.size();int left=0,sum=0,longest=-1;for(int right=0;right<(int)nums.size();++right){sum+=nums[right];while(sum>target)sum-=nums[left++];if(sum==target)longest=max(longest,right-left+1);}return longest<0?-1:nums.size()-longest;} };
